  coatings: [{"name":"TiN","fullname":"Titanium Nitride","color":"Gold","hardness":"HV 2000","maxTemp":"500°C","friction":0.4,"thickness":"2–4 µm","applied":"PVD","materials":"P,M,K,N","notes":"First modern PVD coating. General purpose, decorative gold colour. Good wear resistance, lower performance than modern coatings.","best":"General purpose, HSS tools, low-cost applications"},{"name":"TiAlN","fullname":"Titanium Aluminium Nitride","color":"Violet-Black","hardness":"HV 2800","maxTemp":"900°C","friction":0.45,"thickness":"2–5 µm","applied":"PVD","materials":"P,M,S","notes":"Industry workhorse. Aluminium content provides alumina layer at high temp protecting substrate. Good for dry and semi-dry machining.","best":"Steel, stainless steel, dry or MQL cutting"},{"name":"AlTiN","fullname":"Aluminium Titanium Nitride","color":"Blue-Grey","hardness":"HV 3200","maxTemp":"1000°C","friction":0.35,"thickness":"2–4 µm","applied":"PVD","materials":"N,S","notes":"Higher Al content than TiAlN. Excellent for aluminium (low affinity). Also good for titanium. Harder, lower friction.","best":"Aluminium, titanium, non-ferrous"},{"name":"AlCrN","fullname":"Aluminium Chromium Nitride","color":"Dark Grey","hardness":"HV 3200","maxTemp":"1100°C","friction":0.35,"thickness":"2–5 µm","applied":"PVD","materials":"H,P","notes":"Extremely high oxidation resistance. Chromium replaces titanium. Preferred for hardened steels and hot-work tool steel.","best":"Hardened steel, hard milling, die steel"},{"name":"TiCN","fullname":"Titanium Carbon Nitride","color":"Blue-Grey","hardness":"HV 3000","maxTemp":"400°C","friction":0.25,"thickness":"2–5 µm","applied":"CVD/PVD","materials":"P,M","notes":"Very low friction coefficient. Good for interrupted cuts. Often used as base layer in multi-layer coatings.","best":"Interrupted cuts, low friction required, gear cutting"},{"name":"CVD Al₂O₃","fullname":"Chemical Vapour Deposition Aluminium Oxide","color":"Black/Grey","hardness":"HV 2100","maxTemp":"1200°C","friction":0.55,"thickness":"5–15 µm","applied":"CVD (HT)","materials":"P,M,K","notes":"Thermally inert ceramic. Excellent hot hardness. Standard for turning inserts at high speeds. CVD gives thick coating.","best":"High-speed turning of steel and cast iron"},{"name":"DLC","fullname":"Diamond-Like Carbon","color":"Black","hardness":"HV 5000","maxTemp":"350°C","friction":0.05,"thickness":"1–3 µm","applied":"PVD/PACVD","materials":"N","notes":"Extremely low friction, very hard. Ideal for non-ferrous. Breaks down at high temperatures. Cannot use on ferrous.","best":"Aluminium, copper, graphite, CFRP composites"},{"name":"AlTiN+Si","fullname":"Silicon-reinforced AlTiN (nano-composite)","color":"Dark Violet","hardness":"HV 3800","maxTemp":"1200°C","friction":0.4,"thickness":"2–4 µm","applied":"PVD","materials":"M,S","notes":"Nano-composite with Si₃N₄ amorphous phase. Extremely high hardness and oxidation resistance. Best for superalloys.","best":"Inconel, titanium, stainless steel, heat-resistant alloys"},{"name":"CBN","fullname":"Cubic Boron Nitride","color":"N/A (bulk)","hardness":"HV 4500","maxTemp":"1400°C","friction":0.15,"thickness":"Brazed tip","applied":"Sintered / Brazed","materials":"H","notes":"Second hardest material after diamond. For hard turning ferrous metals. Cannot use on non-ferrous.","best":"Hardened steel HRC 45–65, hard cast iron, HSS"},{"name":"PCD","fullname":"Polycrystalline Diamond","color":"N/A (bulk)","hardness":"HV 8000","maxTemp":"700°C","friction":0.05,"thickness":"Brazed tip","applied":"Sintered / Brazed","materials":"N","notes":"Hardest cutting material. Exceptional life in non-ferrous. Reacts with iron — cannot cut ferrous. High cost, high reward.","best":"Aluminium, copper, CFRP, MMC, Si alloys"}],
  materials: [{"iso":"P","name":"Steel","color":"#3b82f6","sub":"Carbon, alloy, tool and stainless","hardness":"150–280 HB","chipType":"Long","recommended":"TiAlN PVD, CVD Al₂O₃","notes":"Largest material group. Wide range of machinability. Good with all cutting materials."},{"iso":"M","name":"Stainless Steel","color":"#8b5cf6","sub":"Austenitic, martensitic, duplex, PH","hardness":"150–320 HB","chipType":"Long, tangled","recommended":"TiAlN PVD, AlTiN+Si","notes":"Work hardening tendency. Requires sharp edge, high pressure coolant."},{"iso":"K","name":"Cast Iron","color":"#f59e0b","sub":"Grey, nodular, malleable, chilled","hardness":"120–260 HB","chipType":"Short, brittle","recommended":"CVD Al₂O₃, TiCN, CBN","notes":"Abrasive material. Dry machining often preferred. Short chips."},{"iso":"N","name":"Non-Ferrous","color":"#10b981","sub":"Aluminium, copper, brass, zinc","hardness":"40–150 HB","chipType":"Long, built-up","recommended":"AlTiN, DLC, PCD","notes":"Low cutting forces, high speeds possible. Risk of BUE (built-up edge)."},{"iso":"S","name":"Super Alloys & Titanium","color":"#ef4444","sub":"Inconel, Waspaloy, Ti6Al4V, Co alloys","hardness":"150–400 HB","chipType":"Short, serrated","recommended":"AlTiN+Si, TiAlN, PVD","notes":"Most challenging group. Low thermal conductivity. Work hardening. High-pressure coolant essential."},{"iso":"H","name":"Hardened Steel","color":"#1f2937","sub":"Hardened steel HRC 45–65, chilled CI","hardness":"HRC 45–65","chipType":"Short, powdery","recommended":"CBN, AlCrN, ceramic","notes":"Hard turning replacing grinding. Small DOC, high feed concept."}],
